import org.mapstruct.ap.internal.util.Strings;

import static org.mapstruct.ap.internal.util.Collections.first;

public class MapFromIterableMappingMethod extends ContainerMappingMethod {

    public static class Builder extends ContainerMappingMethodBuilder<Builder, MapFromIterableMappingMethod> {

        public Builder() {
            super( Builder.class, "iterable element" );
        }

        @Override
        protected Type getElementType(Type parameterType) {
            if ( parameterType.isMapType() ) {
                List<Type> typeArguments = parameterType.determineTypeArguments( Map.class );
                return ctx.getTypeFactory().getMapEntryType(
                    typeArguments.get( 0 ).getTypeBound(),
                    typeArguments.get( 1 ).getTypeBound()
                );
            }
            return parameterType.isArrayType() ? parameterType.getComponentType() : first(
                parameterType.determineTypeArguments( Iterable.class ) ).getTypeBound();
        }

        @Override
        protected Assignment getWrapper(Assignment assignment, Method method) {
            Type entryType = getElementType( method.getResultType() );
            return new LocalVarWrapper( assignment, method.getThrownTypes(), entryType, false );
        }

        @Override
        protected MapFromIterableMappingMethod instantiateMappingMethod(Method method,
            Collection<String> existingVariables, Assignment assignment, MethodReference factoryMethod,
            boolean mapNullToDefault, String loopVariableName,
            List<LifecycleCallbackMethodReference> beforeMappingMethods,
            List<LifecycleCallbackMethodReference> afterMappingMethods, SelectionParameters selectionParameters,
            PresenceCheck sourceParameterPresenceCheck) {
            return new MapFromIterableMappingMethod(
                method,
                getMethodAnnotations(),
                existingVariables,
                assignment,
                factoryMethod,
                mapNullToDefault,
                loopVariableName,
                beforeMappingMethods,
                afterMappingMethods,
                selectionParameters,
                sourceParameterPresenceCheck,
                getElementType( method.getResultType() )
            );
        }
    }

    private final Type resultElementType;

    private MapFromIterableMappingMethod(Method method, List<Annotation> annotations,
                                         Collection<String> existingVariables, Assignment parameterAssignment,
                                         MethodReference factoryMethod, boolean mapNullToDefault,
                                         String loopVariableName,
                                         List<LifecycleCallbackMethodReference> beforeMappingReferences,
                                         List<LifecycleCallbackMethodReference> afterMappingReferences,
                                         SelectionParameters selectionParameters,
                                         PresenceCheck sourceParameterPresenceCheck, Type resultElementType) {
        super(
            method,
            annotations,
            existingVariables,
            parameterAssignment,
            factoryMethod,
            mapNullToDefault,
            loopVariableName,
            beforeMappingReferences,
            afterMappingReferences,
            selectionParameters,
            sourceParameterPresenceCheck
        );
        this.resultElementType = resultElementType;
    }

    public Type getSourceElementType() {
        Type sourceType = getSourceParameter().getType();
        return sourceType.isArrayType() ? sourceType.getComponentType() : first(
            sourceType.determineTypeArguments( Iterable.class ) ).getTypeBound();
    }

    @Override
    public Type getResultElementType() {
        return resultElementType;
    }

    public String getEntryVariableName() {
        return Strings.getSafeVariableName( "entry", getParameterNames() );
    }
}
